#!/usr/bin/env python3
"""Build an English, self-contained replay of actual paired-image agent loops."""
import argparse
import base64
import io
import json
from pathlib import Path
from PIL import Image

ROOT = Path(__file__).resolve().parents[1]


def build(source, destination):
    data = json.loads(Path(source).read_text())
    all_cases = data['cases']
    selected_ids = data.get('selected_case_ids', {})
    if selected_ids and all(selected_ids.get(k) for k in ('LOW_COST_ONLY', 'HIGH_COST_ANALYSIS')):
        data['cases'] = [next(c for c in all_cases if c['id'] == selected_ids[k])
                         for k in ('LOW_COST_ONLY', 'HIGH_COST_ANALYSIS')]
    if len(data['cases']) != 2 or not data.get('completed'):
        raise ValueError('A completed low-cost and high-cost pair is required for the two-demo view')
    if [c['decision']['action'] for c in data['cases']] != ['LOW_COST_ONLY', 'HIGH_COST_ANALYSIS']:
        raise ValueError('The selected demonstrations must be ordered low-cost, high-cost')
    for c in data['cases']:
        if c['liquid']['status'] != 'success' or c['decision'].get('controller_override'):
            raise ValueError('A selected demo must contain a valid actual Liquid recommendation')
        if not all(c['storage'].get(k) for k in ('read_verified', 'write_verified')):
            raise ValueError('Both memory operations must be verified')
    if data['cases'][0].get('strong') is not None:
        raise ValueError('The local-only demonstration must not contain a GPT-5 call')
    if (data['cases'][1].get('strong') or {}).get('status') != 'success':
        raise ValueError('The high-cost demonstration requires a successful recorded GPT-5 call')
    data['attempts'] = [{'id': c['id'], 'status': c['liquid']['status'],
                         'action': c['decision']['action'],
                         'controller_override': c['decision'].get('controller_override')}
                        for c in all_cases]
    data['source_artifact'] = str(Path(source).resolve().relative_to(ROOT))
    for case in data['cases']:
        for key in ('previous', 'current'):
            obs = case[key]
            path = Path(obs['frame_uri'])
            with Image.open(path if path.is_absolute() else ROOT / path) as im:
                im = im.convert('RGB')
                im.thumbnail((740, 740))
                buf = io.BytesIO()
                im.save(buf, 'JPEG', quality=90)
                obs['preview'] = 'data:image/jpeg;base64,' + base64.b64encode(buf.getvalue()).decode()
    encoded = json.dumps(data, ensure_ascii=False).replace('<', '\\u003c').replace('>', '\\u003e').replace('&', '\\u0026')
    output = Path(destination)
    output.parent.mkdir(parents=True, exist_ok=True)
    output.write_text(HTML.replace('__PAYLOAD__', encoded))
    print(json.dumps({'html': str(output.resolve()), 'cases': len(data['cases'])}))


